data class Task(val id: Int, val title: String, val done: Boolean = false)
fun addTask(tasks: List<Task>, id: Int, title: String): List<Task> {
    require(id > 0 && tasks.none { it.id == id })
    val clean = title.trim()
    require(clean.isNotEmpty())
    return tasks + Task(id, clean)
}
fun main() {
    val initial = listOf(Task(7, "Stock"))
    val updated = addTask(initial, 9, " Pack ")
    println(updated.joinToString("|") { "${it.id}:${it.title}" })
    println(initial.size)
    try { addTask(updated, 9, "Duplicate") } catch (error: IllegalArgumentException) { println("rejected") }
    try { addTask(updated, 0, "Invalid") } catch (error: IllegalArgumentException) { println("rejected") }
    try { addTask(updated, 10, "   ") } catch (error: IllegalArgumentException) { println("rejected") }
    check(initial == listOf(Task(7, "Stock")))
    check(updated.size == 2)
    println(addTask(emptyList(), 1, "First").size)
}
// Expected output:
// 7:Stock|9:Pack
// 1
// rejected
// rejected
// rejected
// 1

data class Task(val id: Int, val title: String, val done: Boolean = false)
fun complete(tasks: List<Task>, id: Int): List<Task> =
    tasks.map { if (it.id == id) it.copy(done = true) else it }
fun remove(tasks: List<Task>, id: Int): List<Task> = tasks.filter { it.id != id }
fun main() {
    val initial = listOf(Task(4, "Pack"), Task(9, "Pack"), Task(12, "Ship", true))
    val completed = complete(initial, 9)
    check(!initial[0].done && !initial[1].done && initial[2].done)
    check(!completed[0].done && completed[1].done && completed[2].done)
    check(complete(completed, 9) == completed)
    check(complete(completed, 99) == completed)
    check(remove(completed, 99) == completed)
    check(complete(emptyList(), 9).isEmpty())
    check(remove(emptyList(), 9).isEmpty())
    val remaining = remove(completed, 4)
    check(remaining.map { it.id } == listOf(9, 12))
    check(remove(remaining, 9) == listOf(Task(12, "Ship", true)))
    println(remaining.joinToString(",") { "${it.id}:${it.done}" })
    println("Checks passed")
}
// Expected output:
// 9:true,12:true
// Checks passed
